SELECT p.gender, EXTRACT(YEAR FROM p.dob) AS age, i.icustay_id, COUNT(DISTINCT d.procedure_id) AS procedure_count, AVG(i.length_of_stay) AS avg_length_of_stay, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) AS mortality_count FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN diagnoses_icd d ON i.hadm_id = d.hadm_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM p.dob) BETWEEN 65 AND 75 AND d.icd_code = '440.0' AND d.icd_version = '2015' AND i.intime <= '2015-07-01' AND (i.outtime >= '2015-07-01' OR i.outtime IS NULL) AND (d.chartdate <= '2015-07-01' OR d.chartdate IS NULL) AND (d.itemid <= '440.0' OR d.itemid IS NULL) GROUP BY p.gender, age, i.icustay_id, i.hadm_id HAVING COUNT(DISTINCT d.procedure_id) > 0 ORDER BY procedure_count DESC, avg_length_of_stay DESC, mortality_count DESC;